def transform(grid):
    h, w = len(grid), len(grid[0])

    def regular_candidates(color):
        rows = [r for r in range(h) if grid[r].count(color) >= 0.65 * w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.65 * h]

        def regular(seq):
            if len(seq) < 2:
                return False
            gaps = [seq[i + 1] - seq[i] for i in range(len(seq) - 1)]
            return gaps[0] >= 2 and all(g == gaps[0] for g in gaps)

        return rows, cols, regular(rows) and regular(cols)

    choices = []
    for color in range(10):
        rows, cols, ok = regular_candidates(color)
        if ok:
            choices.append((len(rows) * len(cols), len(rows) + len(cols), color, rows, cols))

    if choices:
        _, _, line_color, rows, cols = max(choices)
    else:
        return [row[:] for row in grid]

    counts = [0] * 10
    for row in grid:
        for v in row:
            if v != line_color:
                counts[v] += 1
    background = max(range(10), key=lambda v: counts[v])

    out = []
    for i in range(len(rows) - 1):
        out_row = []
        for j in range(len(cols) - 1):
            corners = (grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                       grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]])
            v = corners[0]
            out_row.append(v if v != line_color and all(x == v for x in corners) else background)
        out.append(out_row)

    points = [(r, c) for r in range(len(out)) for c in range(len(out[0]))
              if out[r][c] != background]
    if not points:
        return [[background]]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    return [row[c0:c1 + 1] for row in out[r0:r1 + 1]]
